WITH candidates AS MATERIALIZED (SELECT level.xx_hash,item.name,points.points FROM public.level level JOIN public.level_points points ON points.id_level=level.id AND points.points>=$1 JOIN LATERAL (SELECT source.* FROM public.level_item source WHERE source.id_level=level.id AND source.deleted=false ORDER BY source.updated_at DESC,source.id DESC LIMIT 1) item ON true WHERE level.publicly_visible=true ORDER BY level.id DESC LIMIT 100) SELECT jsonb_build_object('xxHash',xx_hash,'name',name,'points',points) AS value FROM candidates ORDER BY random() LIMIT 1
